import zipfile
import re
from xml.etree import ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

path = 'budget.xlsx'
with zipfile.ZipFile(path) as z:
    print("Files in archive:")
    for n in z.namelist():
        print("  ", n)

    shared = []
    if 'xl/sharedStrings.xml' in z.namelist():
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = wb_root.findall('.//m:sheet', NS)
    print("\nSheet names:", [s.get('name') for s in sheets])

    for sheet in sheets:
        name = sheet.get('name')
        rid = sheet.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
        target = None
        for rel in rels:
            if rel.get('Id') == rid:
                target = rel.get('Target')
                break
        if target is None:
            continue
        if target.startswith('/'):
            sheet_path = 'xl' + target
        else:
            sheet_path = 'xl/' + target
        print(f"\n=== Sheet: {name} ({sheet_path}) ===")
        sroot = ET.fromstring(z.read(sheet_path))
        for row in sroot.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
            for c in row:
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                isel = c.find('m:is', NS)
                val = None
                if v is not None:
                    val = v.text
                elif isel is not None:
                    val = ''.join(x.text or '' for x in isel.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
                if t == 's' and val is not None:
                    val = shared[int(val)]
                if val is not None:
                    print(f"  {ref}: {val!r}")

