import zipfile
from xml.etree import ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
M = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'

def col_num(ref):
    letters = ''.join(ch for ch in ref if ch.isalpha())
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch.upper()) - 64)
    return n

def row_num(ref):
    return int(''.join(ch for ch in ref if ch.isdigit()))

with zipfile.ZipFile('budget.xlsx') as z:
    sroot = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

cells = {}
for row in sroot.iter(M + 'row'):
    for c in row:
        v = c.find(M + 'v')
        if v is not None and v.text is not None:
            cells[(row_num(c.get('r')), col_num(c.get('r')))] = float(v.text)

# Expense rows: category in col A (rows 11-22), sub-item in col B, amount in col C
expense_rows = [(r, cells[(r, 1)], cells[(r, 3)]) for r in range(11, 23) if (r, 1) in cells and (r, 3) in cells]

by_category = {}
total = 0.0
for r, category, amount in expense_rows:
    by_category[category] = by_category.get(category, 0.0) + amount
    total += amount

print("Expenses by category:")
for cat in sorted(by_category, key=lambda c: -by_category[c]):
    print(f"  {cat}: {by_category[cat]:,.2f}")
print(f"TOTAL EXPENSES: {total:,.2f}")
print(f"Line items counted: {len(expense_rows)}")

